UPDATE `sourcelead`.`MODULES` SET `MODULE_NAME`='ATS' WHERE `ID`='1';
UPDATE `sourcelead`.`MODULES` SET `MODULE_NAME`='VMS' WHERE `ID`='2';
UPDATE `sourcelead`.`MODULES` SET `MODULE_NAME`='TIMESHEET' WHERE `ID`='3';

UPDATE `sourcelead`.`TABS` SET `TAB_ID`='4' WHERE `ID`='5';
UPDATE `sourcelead`.`TABS` SET `TAB_ID`='4' WHERE `ID`='6';


ALTER TABLE `sourcelead`.`ROLES` DROP INDEX `DISPLAY_NAME` ;




DROP TABLE IF EXISTS `sourcelead`.`SOURCELEAD_ACTIONS`;
CREATE TABLE `sourcelead`.`SOURCELEAD_ACTIONS` (
  ID BIGINT NOT NULL AUTO_INCREMENT,
  ACTION_NAME TEXT DEFAULT NULL,
  ACTION_ROLE VARCHAR(100) DEFAULT NULL,
  TAB_ID BIGINT,
  PRIMARY KEY (`ID`),
  FOREIGN KEY(TAB_ID) REFERENCES `sourcelead`.`TABS`(ID)
) ;


DROP TABLE IF EXISTS `sourcelead`.`MODULE_ACTIONS`;
CREATE TABLE `sourcelead`.`MODULE_ACTIONS` (
  ID BIGINT NOT NULL AUTO_INCREMENT,
  MODULE_ID BIGINT,
  ACTION_ID BIGINT,
  PRIMARY KEY (`ID`),
  FOREIGN KEY(MODULE_ID) REFERENCES `sourcelead`.`MODULES`(ID),
  FOREIGN KEY(ACTION_ID) REFERENCES `sourcelead`.`SOURCELEAD_ACTIONS`(ID)
) ;














































